        message_size,
        is_read,
        is_flagged,
        preview_text,
    );

    if let Err(nserror::NS_MSG_MESSAGE_NOT_FOUND) = result {
        log::debug!("Creating message {message_id}");

        self.listener.on_message_created(
            message_id,
            header_block,
            message_size,
            is_read,
            is_flagged,
            preview_text,
        )?;
    } else {
        result?;
        log::debug!("Updated message {message_id}");
    }
